using EchoSphere.Core;using System.Text.Json;
static partial class Program {
 static void MetaProgression(string path){
  var rows=new List<object>();var incomes=new List<double>();int comparisons=0;long oldShop=0,newShop=0;var prices=new List<object>();
  foreach(string id in PersistentUpgradeRules.Ids){long old=0,now=0;var levels=new List<int>();for(int level=0;level<PersistentUpgradeRules.GetMaxLevel(id);level++){old+=(int)Math.Floor(PersistentUpgradeRules.GetBaseCost(id)*Math.Pow(3,level));int cost=PersistentUpgradeRules.GetCost(id,level);now+=cost;levels.Add(cost);}oldShop+=old;newShop+=now;prices.Add(new{id,levels,total=now,oldTotal=old});}
  int shards=CharacterRules.All.Sum(c=>MetaCurrencyRules.CharacterUnlockShards(c.UnlockCost));var samples=new Dictionary<string,List<double>>();
  for(uint seed=1;seed<=512;seed++)foreach(EchoRegionId region in Enum.GetValues<EchoRegionId>())foreach(var profile in Profiles){var events=Events(seed,region,profile);foreach(int duration in new[]{300,900,1800}){bool complete=duration==1800;var collected=events.Where(e=>e.Time<=duration).ToList();int bosses=collected.Count(e=>e.Boss),kills=collected.Count(e=>!e.Boss),elites=collected.Count(e=>e.Elite);int credit=MetaCurrencyRules.RunCredits(duration,bosses,kills,complete,region,elites);int old=(int)Math.Floor(Math.Floor((double)duration)*.15+bosses*25d+kills*.05)+(complete?RegionBossScheduleRules.GetBaseGoldReward(region)+elites*5+bosses*35:0);if(credit!=old)throw new Exception("Run credit formula changed");comparisons++;double hours=(duration+60)/3600d;double hourly=credit/hours;string key=profile.Name+":"+duration;if(!samples.TryGetValue(key,out var list))samples[key]=list=new();list.Add(hourly);}}
  foreach(var pair in samples){var sorted=pair.Value.Order().ToArray();double median=sorted[sorted.Length/2];rows.Add(new{profileDuration=pair.Key,samples=sorted.Length,creditsPerHour=median,p95=sorted[(int)(sorted.Length*.95)],shopHours=newShop/median,oldShopHours=oldShop/median});}
  double endlessCeiling=3600d/RegionBossScheduleRules.EndlessBossIntervalSeconds;double minimumHours=shards/endlessCeiling;
  if(minimumHours<120)throw new Exception("All-character optimistic boss ceiling below120hours");
  double fastestCredits=samples.Where(p=>p.Key.EndsWith(":1800")).SelectMany(p=>p.Value).Max();double shopMinimumHours=newShop/fastestCredits;if(shopMinimumHours<120)throw new Exception("Shop completion below120h at modeled credit ceiling");
  var result=new{fastestModeledCreditsPerHour=fastestCredits,minimumShopHoursInModeledWins=shopMinimumHours,scope="Economy throughput model, not player/AI/device simulation.512seeds x6regions x4enemy-lifetime/collection profiles x3run lengths.60seconds between runs. Stabilization modeled as win at30minutes; real win rate, exploration and challenge difficulty are not predicted. Endless assumes every scheduled boss instantly killed; ignores initial delay, giving optimistic upper bound24shards/hour. No elapsed-day gate. Existing balances/progress retained.",comparisons,characterTotalShards=shards,earliestAllCharactersHoursAtEndlessCeiling=minimumHours,daysAt1Hour=minimumHours,daysAt1_5Hours=minimumHours/1.5,daysAt2Hours=minimumHours/2,firstCharacterShards=MetaCurrencyRules.CharacterUnlockShards(1500),stabilizationShardsPer30Minutes=MetaCurrencyRules.RunShards(3,true),oldShopTotal=oldShop,newShopTotal=newShop,prices,scenarios=rows};Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"Meta economy: {comparisons} income equivalence comparisons PASS; characters{shards}Shards >= {minimumHours:F1}h optimistic Endless, {minimumHours/2:F1}days at2h/day. Shop {oldShop} -> {newShop}Credits. {path}");
 }
